// Types for the rules data generated by `npm run data` (scripts/extract/build.py).
// Text fields are Markdown-lite: **bold**, _italic_, paragraphs split by "\n\n",
// list items on their own line starting with "• " or "◦ ".

export type TraitId = 'agility' | 'strength' | 'finesse' | 'instinct' | 'presence' | 'knowledge';
export type DomainId =
  | 'arcana' | 'blade' | 'bone' | 'codex' | 'dread'
  | 'grace' | 'midnight' | 'sage' | 'splendor' | 'valor';
export type RangeId = 'melee' | 'very-close' | 'close' | 'far' | 'very-far';
export type Tier = 1 | 2 | 3 | 4;

export interface Feature {
  id: string;
  name: string;
  text: string;
  /** Sidebar tip or note printed next to the feature. */
  note?: string;
}

export interface HopeFeature extends Feature {
  hopeCost: number;
}

export interface Subclass {
  id: string;
  name: string;
  description: string;
  /** null for subclasses without a Spellcast trait (Brawler, Guardian, Warrior). */
  spellcastTrait: TraitId | null;
  foundation: Feature[];
  specialization: Feature[];
  mastery: Feature[];
}

export interface Beastform {
  id: string;
  name: string;
  tier: Tier;
  examples: string;
  trait: TraitId | null;
  traitBonus: number;
  evasionBonus: number;
  attack: { range: RangeId; trait: TraitId; damage: string; type: 'phy' | 'mag' } | null;
  advantages: string[];
  features: Feature[];
  text: string;
}

export interface Stance extends Feature {
  tier: Tier;
}

export interface TitledText {
  title: string;
  text: string;
}

export interface ClassExtras {
  beastforms?: { rules: string; forms: Beastform[] };
  martialStances?: { rules: TitledText[]; stances: Stance[] };
  companion?: {
    steps: TitledText[];
    exampleExperiences: string[];
    rules: TitledText[];
    levelUpOptions: Feature[];
  };
  patronSpheres?: string[];
}

export interface ClassDef {
  id: string;
  name: string;
  description: string;
  domains: [DomainId, DomainId];
  startingEvasion: number;
  startingHitPoints: number;
  classItems: string;
  hopeFeature: HopeFeature;
  features: Feature[];
  subclasses: [Subclass, Subclass];
  backgroundQuestions: string[];
  connectionQuestions: string[];
  extras: ClassExtras;
}

export interface WeaponRef {
  /** Weapon id in weapons.json, or null for a class weapon (Brawler’s Strike). */
  id: string | null;
  name: string;
  trait?: TraitId;
  range?: RangeId;
  damage?: string;
  type?: 'phy' | 'mag';
}

export type DescriptionKey = 'clothes' | 'eyes' | 'body' | 'skin' | 'attitude';

export interface Guide {
  source: 'guide';
  traits: Record<TraitId, number>;
  primary: WeaponRef;
  secondary: WeaponRef | null;
  armor: { id: string; name: string };
  inventory: {
    take: string[];
    chooseOne: string[];
    classItem: string[];
    spellCarrier: string[];
    spellCarrierPrompt: string;
  };
  description: Record<DescriptionKey, string[]>;
}

export interface Ancestry {
  id: string;
  name: string;
  description: string;
  /** Mixed ancestry takes features[0] from one ancestry and features[1] from another. */
  features: [Feature, Feature];
  group?: 'Elemental Kin';
}

/** A transformation card (SRD "Transformations"): two features and six questions. */
export interface Transformation {
  id: string;
  name: string;
  description: string;
  features: [Feature, Feature];
  questions: string[];
}

export interface Community {
  id: string;
  name: string;
  description: string;
  adjectives: string[];
  feature: Feature;
}

export interface DomainCard {
  id: string;
  name: string;
  domain: DomainId;
  level: number;
  type: 'ability' | 'spell' | 'grimoire';
  recallCost: number;
  text: string;
}

export interface Damage {
  die: number;
  bonus: number;
  type: 'phy' | 'mag' | 'phy/mag';
}

export interface ItemFeature {
  name: string;
  text: string;
}

export interface Weapon {
  id: string;
  name: string;
  tier: Tier;
  category: 'primary' | 'secondary';
  /** 'spellcast' = use your Spellcast trait (Arcane-Frame Wheelchair). */
  trait: TraitId | 'spellcast';
  range: RangeId;
  damage: Damage;
  /** Hands occupied. */
  burden: 1 | 2;
  feature: ItemFeature | null;
  group?: 'combat-wheelchair';
}

export interface Armor {
  id: string;
  name: string;
  tier: Tier;
  thresholds: { major: number; severe: number };
  score: number;
  feature: ItemFeature | null;
}

export interface Loot {
  id: string;
  name: string;
  kind: 'item' | 'consumable';
  /** d12 table result. */
  roll: number;
  set: 'core' | 'additional';
  text: string;
}

export interface DowntimeMove {
  id: string;
  name: string;
  text: string;
}

export type AdvancementId =
  | 'traits' | 'hitPoint' | 'stress' | 'experiences' | 'domainCard'
  | 'evasion' | 'subclass' | 'proficiency' | 'multiclass';

export interface Advancement {
  id: AdvancementId;
  text: string;
  /** Advancement picks this option uses (Proficiency and Multiclass take both). */
  cost: 1 | 2;
  minTier: 2 | 3;
  /** Checkbox slots per tier, counted from the official character sheet. */
  slots: Record<'2' | '3' | '4', number>;
}

export interface Rules {
  creation: {
    level: number;
    stress: number;
    hope: number;
    proficiency: number;
    traitModifiers: number[];
    experiences: { count: number; modifier: number };
    domainCards: { count: number; level: number };
    startingInventory: { take: string[]; chooseOne: string[]; notes: string[] };
    exampleExperiences: Record<'backgrounds' | 'characteristics' | 'specialties' | 'skills' | 'phrases', string[]>;
  };
  caps: {
    hope: number;
    armorScore: number;
    loadout: number;
    hitPointSlots: number;
    stressSlots: number;
    proficiency: number;
    consumablesEach: number;
  };
  downtime: {
    movesPerRest: number;
    shortRestsBeforeLong: number;
    intro: string;
    short: { moves: DowntimeMove[]; end: string };
    long: { moves: DowntimeMove[]; end: string };
  };
  leveling: {
    tiers: { tier: Tier; levels: [number, number] }[];
    achievements: { level: number; newExperience: number; proficiency: number; clearMarkedTraits: boolean }[];
    advancementsPerLevel: number;
    advancements: Advancement[];
    advancementRules: string;
    thresholdIncrease: number;
    domainCardStep: string;
    multiclass: { minLevel: number; text: string };
    domainCardLevelLimits: Record<'2' | '3' | '4', number>;
  };
  gold: {
    denominations: ['coins', 'handfuls', 'bags', 'chests'];
    perNext: number;
    maxChests: number;
    coinsOptional: boolean;
    text: string;
  };
  death: { intro: string; moves: { id: 'blaze-of-glory' | 'avoid-death' | 'risk-it-all'; name: string; text: string }[] };
}

export interface MixedAncestryRule {
  id: 'mixed';
  name: string;
  text: string;
}
